BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
P=[['希腊 prássein／práttein','做、实行、完成']]
K=P+[['希腊 praktós → praktikós → 后期拉丁 practicus','做成的、可做的 → 与行动和实际事务有关的']]
V=K+[['中世纪拉丁 practicāre → 古法语 pratiser／practiser → 中古英语 practisen','实行、从事；反复做以熟练'],['英语 practise／practice','英式动词通常用 practise；美式动词用 practice']]
N=V[:-1]+[['英语 practice','实行 → 练习、惯例、执业与专业业务']]
A=K+[['中世纪拉丁 practicālis；法语及英语 practic + -al 等路线','行动、实际应用方面的'],['英语 practical','实际的；实用的；动手的']]
G=P+[['希腊 prâgma／pragmat- → pragmatikós → 拉丁 pragmaticus','做出的事、事务 → 善于处理事务的'],['法语 pragmatique／英语 pragmatical 缩短等路线 → pragmatic','经历事务性及旧贬义用法，发展为重事实、讲实效的']]
ABLE=K+[['中世纪拉丁 practicāre → 法语 pratiquer／pratiquable；也有拉丁 practicābilis 借入分析','实行 → 能够实行的'],['英语 practicable','在现实条件下可实施的']]
W=[
E('practice','/ˈpræktɪs/','练习；实践；惯例；执业、诊所业务；练习、从业〔美式动词〕','把事情真的做出来；反复做是练习，经常这样做就成了惯例。','经中古英语 practisen 相关名词用法，接法语 pratiser／practiser、拉丁 practicāre，再接希腊 praktikós“与行动有关的”。现代 practice 是整词，不能切成 prac + tice。',N,'piano practice 是钢琴练习；in practice 是在实际操作中；common practice 是常见做法；a medical practice 可以指医生的执业业务或诊所。美式 practice 也作动词，英式动词多写 practise。','put into practice；in practice；common practice；practice doing something〔美〕；a private practice。','practice 不总是“练习”：business practices 是商业做法，不能译成商业训练。experience 更泛指经历积累，不一定来自反复训练。',('The idea sounds simple, but it is difficult to put into practice.','这个想法听起来简单，实际实行却不容易。'),('It is common practice to keep a copy of the receipt.','保留一份收据副本是常见做法。'),('She practices the piano for twenty minutes each morning.','她每天早晨练二十分钟钢琴。'),sources=['https://www.etymonline.com/word/practice']),
E('practise','/ˈpræktɪs/','练习；实行；从事专业工作〔英式动词〕','亲手去做，可以是为熟练而反复做，也可以是正式从事这项工作。','与 practice 动词同一历史路线；英式拼写用 -ise 区分动词与名词，不能把词尾的 s 当成另一个词根。',V,'practise speaking English 是练习说英语；practise medicine 是行医，不是还没资格上岗的“练习医生”。后接另一个动作时常用 -ing，不用 practise to do。','practise doing；practise the piano；practise law；practise what you preach。','英式名词 practice、动词 practise 读音相同；美式两种词性通常都写 practice。',('We practise introducing ourselves in pairs.','我们两人一组练习自我介绍。'),('He practises law in a small coastal town.','他在一座海滨小城从事律师工作。'),sources=['https://en.wiktionary.org/wiki/practise#English','https://www.etymonline.com/word/practice']),
E('practical','/ˈpræktɪkəl/','实用的；实际的；动手能力强的；实操课或考试','把想法拿到真实生活中，看它能不能用、好不好用。','历史包含中世纪拉丁 practicālis 借入及较早 practic 加 -al 等路线；远源希腊 praktikós。现代与 practice 一看相关，却不能只说 practice 加 -al 就完成了历史说明。',A,'practical advice 是能拿来用的建议；a practical person 常说会解决生活中的具体问题；practical experience 是亲自做过的经验。a practical 可指实操课或实操考试。','practical advice；practical experience；a practical solution；practical skills。','practicable 重点是做得到；practical 还可说有用、方便、会动手。一件事能做得到，却未必是好用的选择。',('She gave me practical advice on organising the workspace.','她给了我整理工作区的实用建议。'),('The course combines lectures with practical work.','这门课把讲授与实操结合起来。'),sources=['https://www.etymonline.com/word/practical','https://en.wiktionary.org/wiki/practical#English']),
E('practically','/ˈpræktɪkli/','几乎；从实际角度；在实践中','常用义是“实际效果已经差不多等于”，所以能表示几乎。','practical + -ly；由实际方面的副词用法，延伸出“实际上近乎如此”的程度义。',A+[['英语 practical + -ly → practically','从实际方面 → 实际效果近乎、几乎']],'practically empty 是几乎空了，不是“实用地空”；practically speaking 是从实际角度说。判断它修饰的是程度，还是处理事情的方式。','practically everyone；practically impossible；practically empty；practically speaking。','practically 在程度义上接近 almost；pragmatically 强调务实地处理问题，不能拿来替换 practically everyone。',('By midnight, the streets were practically empty.','到午夜时，街上几乎空无一人。'),('Practically speaking, we need a room closer to the entrance.','从实际使用来看，我们需要一间离入口更近的房间。'),sources=['https://en.wiktionary.org/wiki/practically#English','https://www.etymonline.com/word/practically']),
E('practicality','/ˌpræktɪˈkæləti/','实用性；可行性；具体事务〔常用复数〕','不只问点子好不好听，还问空间、钱和时间能不能配合。','practical + -ity，重音移到 -cal- 所在音节；由实际、有用这一特点组成名词。',A+[['英语 practical + -ity → practicality','实用、现实可行的性质；实际要处理的事项']],'question the practicality of a plan 是怀疑计划在现实中是否好实行；the practicalities of moving 是搬家要处理的运输、时间等细节。复数常是具体问题，不只是抽象实用性。','the practicality of；question its practicality；deal with the practicalities。','practicality 可以评价方案，也可以用复数指具体事务；practice 多指行动、惯例或练习，不等于实用性。',('We liked the design but questioned its practicality.','我们喜欢这个设计，却怀疑它是否实用。'),('They discussed the practicalities of moving the office.','他们讨论了办公室搬迁的具体安排。'),sources=['https://en.wiktionary.org/wiki/practicality#English']),
E('impractical','/ɪmˈpræktɪkəl/','不实用的；不切实际的；不擅长处理实际事务的','纸面上也许漂亮，真正用起来却太麻烦、太贵或不合适。','in-“不”在 p 前同化为 im-，加 practical；不是 important 的缩略，也不表示“把东西放进去”。',A+[['英语 im- + practical → impractical','缺少现实用途或操作上的合理性']],'an impractical design 可能能造出来，却不好用；an impractical person 常指不擅长日常实际安排。它不必达到绝对做不到的程度。','an impractical idea；impractical clothing；impractical for daily use。','impracticable 更集中于实际条件下做不到；impractical 更宽，常说不合用、不现实。',('White shoes are impractical for walking through muddy fields.','穿白鞋走泥泞田地并不实用。'),('The plan became impractical when the budget was cut.','预算削减后，这项计划变得不切实际。'),sources=['https://en.wiktionary.org/wiki/impractical#English']),
E('practicable','/ˈpræktɪkəbəl/','可实施的；行得通的','不是仅仅想得出来，而是用现有或可取得的条件能做成。','接法语 pratiquable“可实行的”，较远来自拉丁 practicāre；也有拉丁 practicābilis 借入分析。现代可按 practice + -able 理解，但不限定为英语内部首次造词。',ABLE,'a practicable solution 是能实际执行的方案；as soon as practicable 是条件允许时尽快。这个词常见于较正式的方案、制度说明中。','a practicable solution；where practicable；as soon as practicable。','practical 还可说实用、会动手；practicable 主要说方案或行动可实施，通常不用来夸一个人能干。',('We need a practicable way to inspect the roof.','我们需要一种实际可行的屋顶检查办法。'),('The changes will be introduced as soon as practicable.','这些改动将在条件允许时尽快实施。'),sources=['https://www.etymonline.com/word/practicable','https://en.wiktionary.org/wiki/practicable#English']),
E('impracticable','/ɪmˈpræktɪkəbəl/','不可实施的；现实条件下行不通的','把所需的人、钱、时间一摆出来，发现这条路走不通。','否定前缀 in- 在 p 前变为 im-，加 practicable；是“可实施”的反面。',ABLE+[['英语 im- + practicable → impracticable','在实际条件下无法实行的']],'an impracticable deadline 是现实中无法按期完成的期限；impracticable under current conditions 把限制说清楚，并不声称永远不可能。','impracticable to do；impracticable under；render a plan impracticable。','impossible 可说逻辑或事实上的不可能；impracticable 常把重点放在现实资源和条件的限制。',('It would be impracticable to interview every resident in one day.','一天内采访每位居民在现实中行不通。'),('The narrow entrance made the proposed delivery method impracticable.','狭窄的入口使拟定的运送办法无法实施。'),sources=['https://www.etymonline.com/word/impracticable','https://en.wiktionary.org/wiki/impracticable#English']),
E('practitioner','英 /prækˈtɪʃənə/；美 /prækˈtɪʃənər/','从业者；执业人员；实践者','不是只研究这门工作，而是在实际做这门工作的人。','由早期英语 practitian／practician 加 -er，并受 parishioner 一类词形影响；前者经法语 practicien 接拉丁 practicus。不能机械拆成 practice + tion + er。',K+[['古法语 practicien → 英语 practitian／practician','实际从业的人'],['英语 practitian + -er → practitioner','增加词尾，并受 parishioner 类推形成今形']],'a medical practitioner 是医疗执业者；general practitioner 常指全科医生；an experienced practitioner 也可以是设计、教育等领域的资深实务工作者。','a medical practitioner；a general practitioner；an experienced practitioner；a practitioner of an art。','professional 范围更宽，可强调职业身份或专业水平；practitioner 特别强调实际从事某专业或技艺。',('The workshop brings researchers and practitioners together.','这个工作坊把研究者和实际从业者聚到一起。'),('She is an experienced practitioner of community theatre.','她是经验丰富的社区戏剧工作者。'),sources=['https://www.etymonline.com/word/practitioner','https://www.oxfordlearnersdictionaries.com/definition/english/practitioner']),
E('practised','/ˈpræktɪst/','熟练的；练过的〔英式〕','做得多了，动作自然顺手，眼睛也知道该看哪里。','practise + -ed 的过去分词形容词化；末尾读 /st/，不是 /sɪd/。美式常写 practiced。',V+[['英语 practise + -ed → practised','经反复练习的 → 熟练老到的']],'a practised eye 是训练有素的眼光；with practised ease 是做得娴熟自然。也可以是动词过去式：she practised yesterday。','a practised eye；a practised hand；with practised ease；practised in。','practised 说明有经验、做得熟；practical 说明实用或善于实际事务，两者不是拼写变体。',('With a practised hand, she repaired the torn page.','她手法娴熟地修好了撕破的书页。'),('His practised eye noticed the tiny crack immediately.','他凭老练的眼光立刻发现了那道细裂纹。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/practised','https://www.etymonline.com/word/practiced']),
E('practiced','/ˈpræktɪst/','熟练的；练习过的〔美式〕','多次做过之后，不再每一步都停下来想。','practice + -ed；美式动词 practice 的过去式、过去分词，也作熟练的形容词。与英式 practised 同源同音。',V+[['美式英语 practice + -ed → practiced','练习过 → 熟练的']],'a practiced speaker 是有经验的演讲者；a practiced smile 有时说笑容练得很熟，可能带一点刻意。作形容词时不只交代某次练过，而是突出熟练程度。','a practiced speaker；a practiced smile；practiced at；with practiced ease。','practiced 与 practised 是拼写习惯差别；practicing 通常说正在从事、仍在执业，未必等于已经非常熟练。',('She answered the questions with practiced ease.','她娴熟自如地回答了这些问题。'),('The practiced speaker adjusted his pace to the audience.','这位老练的演讲者根据听众调整了节奏。'),sources=['https://www.etymonline.com/word/practiced','https://www.oxfordlearnersdictionaries.com/definition/english/practised']),
E('malpractice','/ˌmælˈpræktɪs/','专业失当行为；执业过失','本来应当按专业标准做好，却出现了严重不当做法。','mal-“坏、不当” + practice“专业执业、做法”；不是“练习得不好”这么宽泛。',N+[['英语 mal- + practice → malpractice','专业活动中的不当行为、过失']],'medical malpractice 常说医疗执业过失；financial malpractice 可指财务方面的不当操作。它带有专业或制度规范的背景，具体法律成立条件另由当地规则决定。','medical malpractice；professional malpractice；allegations of malpractice。','mistake 只是错误；malpractice 通常涉及专业责任或不当行为，不能把每次小失误都直接称为 malpractice。',('The report described financial malpractice within the organisation.','报告描述了该机构内部的财务不当行为。'),('The course includes a discussion of professional malpractice.','课程包含对专业失当行为的讨论。'),sources=['https://www.etymonline.com/word/malpractice','https://en.wiktionary.org/wiki/malpractice#English']),
E('pragmatic','/præɡˈmætɪk/','务实的；讲求实际效果的；语用的','先看眼下有哪些条件，再选一个能真正解决问题的办法。','经法语 pragmatique 或较早英语 pragmatical 缩短等路线，接拉丁 pragmaticus、希腊 pragmatikós，来自 prâgma“做出的事、事务”。并非 pragmatic 就是 practice 加词尾。',G,'a pragmatic solution 可能不完美，但照顾现实限制；a pragmatic leader 会考虑执行结果。语言学中的 pragmatic meaning 指结合语境、说话目的理解的意义，不能一律译成务实。','a pragmatic approach；a pragmatic solution；pragmatic considerations；pragmatic meaning。','practical 常说东西好用或人会动手；pragmatic 更强调处理问题时重现实效果、不固守抽象方案。',('They chose a pragmatic compromise that both teams could accept.','他们选择了一个双方都能接受的务实折中方案。'),('The request has a different pragmatic meaning in this context.','在这个语境中，这个请求具有不同的语用含义。'),sources=['https://www.etymonline.com/word/pragmatic','https://en.wiktionary.org/wiki/pragmatic#English']),
E('pragmatism','/ˈpræɡmətɪzəm/','务实态度；实用主义','判断办法时重视它实际能带来什么，而不只看理论上多漂亮。','取希腊 prâgma 的词干 pragmat- 加 -ism；哲学名称的发展也与德语 Pragmatismus 等讨论有关，不能把哲学全部缩成“只认眼前利益”。',P+[['希腊 prâgma／pragmat- + -ism → pragmatism','事务、行动 → 重实际处理的态度'],['哲学语境中的 pragmatism','以实践后果等理解概念、知识的哲学传统；有多种具体主张']],'political pragmatism 常说政治上的务实；哲学中的 Pragmatism 是一组有历史脉络的思想。日常说某人有 pragmatism，不等于他信奉特定哲学家。','a spirit of pragmatism；political pragmatism；a balance of idealism and pragmatism。','opportunism 是为了眼前利益投机；pragmatism 重视现实效果，本身不必含不守原则或自私的意思。',('A little pragmatism helped us finish with the resources we had.','多一点务实态度，帮助我们利用现有资源完成了工作。'),('The seminar traces the development of American pragmatism.','研讨课梳理美国实用主义哲学的发展。'),sources=['https://www.etymonline.com/word/pragmatism','https://en.wiktionary.org/wiki/pragmatism#English']),
E('pragmatist','/ˈpræɡmətɪst/','务实的人；实用主义者','知道理想是什么，也愿意先找眼下能走通的路。','以希腊来源 pragmat- 接 -ist“持这种立场的人”；与 pragmatic、pragmatism 同属行动、事务词族。现代可把它理解为 pragmatism 的人物名称。',P+[['希腊来源 pragmat- + -ist → 英语 pragmatist','重现实处理的人；实用主义哲学的支持者']],'a pragmatist 会问预算够不够、谁来做、何时能完成；哲学讨论中可明确指实用主义思想家。它不是“不懂理论的人”的固定称呼。','a political pragmatist；a committed pragmatist；an idealist and a pragmatist。','realist 强调看清现实；pragmatist 更突出依照现实条件采取有效办法。两种特点可以在同一人身上。',('As a pragmatist, she asked which option could be implemented this week.','作为一个务实的人，她问哪个方案本周就能实施。'),('The book compares several pragmatists without treating them as identical thinkers.','这本书比较了几位实用主义者，没有把他们当作思想完全相同的人。'),sources=['https://www.etymonline.com/word/pragmatism','https://en.wiktionary.org/wiki/pragmatist#English']),
E('pragmatically','/præɡˈmætɪkli/','务实地；从语用角度','不在理想图纸前停住，转而处理眼前可解决的部分。','pragmatic + -ally，也有由 pragmatical + -ly 的分析；形容词转成描述处理方式的副词。',G+[['英语 pragmatic + -ally／pragmatical + -ly → pragmatically','以务实方式；从语言使用情境看']],'approach a problem pragmatically 是务实处理问题；pragmatically appropriate 在语言学中说表达适合当前交际语境。两种用法都需要看上下文。','deal with pragmatically；approach pragmatically；pragmatically appropriate。','practically 还经常表示“几乎”；pragmatically 不承担这个程度义。pragmatically everyone 不是“几乎人人”。',('We dealt with the shortage pragmatically by sharing the equipment.','我们通过共用设备，务实地应对了短缺。'),('The sentence is grammatical but pragmatically awkward in this conversation.','这句话语法正确，但放在这段对话里不太得体。'),sources=['https://en.wiktionary.org/wiki/pragmatically#English']),
E('praxis','/ˈpræksɪs/','实践；把理论落实为行动〔学术用语〕','读完一套道理之后，实际怎样去做，并从行动中回头理解它。','借拉丁 praxis 及其希腊来源 prâxis“行动、活动”，接 prássein“做”。它与 practice 同源，但不是从现代 practice 剪掉几个字母。',P+[['希腊 prâxis → 拉丁 praxis；希腊也可直接借入 → 英语 praxis','行动、实践，尤其理论付诸行动']],'educational praxis 常讨论教育理念如何在课堂行动中落实、反思；日常钢琴练习通常说 practice。praxis 常带理论与行动相互联系的学术背景。','theory and praxis；educational praxis；political praxis。','practice 范围宽，日常也常用；praxis 偏学术，通常不需要拿它替换普通练习。',('The chapter connects educational theory with classroom praxis.','这一章把教育理论与课堂实践联系起来。'),('Their discussion treated reflection as part of praxis.','他们在讨论中把反思视为实践的一部分。'),sources=['https://en.wiktionary.org/wiki/praxis#English','https://www.etymonline.com/word/praxis']),
E('chiropractic','/ˌkaɪərəˈpræktɪk/','脊椎指压疗法；整脊；相关的','名称原意近于“用手操作”，现指特定的保健与执业领域。','近代英语造词，chiro-“手”接希腊 kheír，practic 接 praktikós“与行动有关的”。词源说的是手法，不保证某项治疗的效果。',[['希腊 kheír；praktikós','手；与行动有关的'],['近代英语 chiro- + practic → chiropractic','以手法操作为突出特征的保健领域名称']],'chiropractic care 常涉及手法治疗，包括脊柱操作，也可能包括运动等其他方式。chiropractic clinic 是提供这类服务的诊所；名称本身不是“任何疾病都能靠整脊治疗”的结论。','chiropractic care；a chiropractic clinic；chiropractic treatment。','chiropractic 是特定专业领域；massage 是按摩，physical therapy 是物理治疗，不能因都可能用手就混作同一个词。',('The article examines research on chiropractic care.','这篇文章考察了关于整脊服务的研究。'),('The clinic’s website lists its chiropractic services.','诊所网站列出了它提供的整脊服务。'),sources=['https://www.etymonline.com/word/chiropractic','https://www.nccih.nih.gov/health/chiropractic-in-depth']),
E('pragma','/ˈpræɡmə/','编译指示〔计算机〕','写给编译工具的一条特别交代：这部分代码请按指定方式处理。','远源希腊 prâgma“事务、做出的事”。现代计算机名称有由 pragmatic 逆构或缩短较早 pragmat 的分析，确切命名路线不宜只选一种。',P+[['希腊 prâgma／pragmat-','做出的事、事务'],['计算机术语 pragma','可能由 pragmatic 逆构或较早 pragmat 缩短；编译处理指示']],'C、C++ 中的 #pragma 可给实现特定的处理指示；不同编译器支持的具体 pragma 可能不同。它不是通常运行时逐行执行的普通函数调用。','a compiler pragma；a pragma directive；support a pragma。','comment 通常供人阅读；pragma 会被支持它的工具解释。不能把所有注释都当成有效编译指示。',('The compiler ignored the pragma it did not recognise.','编译器忽略了它不认识的那条编译指示。'),('Check the compiler documentation before using a platform-specific pragma.','使用特定平台的编译指示前，先查阅编译器文档。'),sources=['https://en.wiktionary.org/wiki/pragma#English','https://gcc.gnu.org/onlinedocs/gcc/Pragmas.html'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C1111')
