ROOT=[dict(id='C1111',meaning='做；行动；实际事务',core='prag-／pract-／prax- = do：从想法走到实际行动。',image='先实际做是 practice；做得多就 practised；能拿来用是 practical；面对限制仍找有效办法是 pragmatic。',intro='希腊 prássein／práttein 表示做、实行。prâgma 是做出的事或事务，prâxis 是行动，praktikós 是与行动有关的。这些旁支分别进入英语，不能把每个词都说成从现代 practice 加几个字母而来。',forms='prag- 出现在 pragmatic；pract- 出现在 practice、practical；prax- 出现在 praxis。practitioner 经 practitian／practician 演化，不是 practice + tion + er。',branches=[['实际行动与熟练','practice、practise、practised、practiced、practitioner、malpractice'],['好用与可做','practical、practically、practicality、impractical、practicable、impracticable'],['处理现实事务','pragmatic、pragmatism、pragmatist、pragmatically'],['理论与专业用法','praxis、chiropractic、pragma']],contrasts='practical 问是否实际好用，practicable 问是否做得到，pragmatic 问是否按现实条件求有效结果。practically 还常表示几乎，pragmatically 没有这一程度义。',practice='用 practical advice、a practicable plan、a pragmatic compromise 各描述一个工作场景；再把名词 practice 和英式动词 practise 区分。',words=[k for k in family if k not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/practice','https://www.etymonline.com/word/practical','https://www.etymonline.com/word/pragmatic'])]
assert {x['word'] for x in W}==set(family)-set(excluded)
assert len(W)==len({x['word'] for x in W})
assert all(x['word'] in m['owned_words'] for x in W)
for x in W:
 assert len(x['examples'])>=2 and len(x['history'])>=2 and x['ipa'],x['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history']),x['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_50_prag.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C1111',len(W),'new',len(ROOT[0]['words']),'references',sum(len(x['examples']) for x in W),'examples')
